class Solution {
  public int ribbonTotalsTotalReceipt(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int total=0;for(int x:a){total+=x;out.add(total);}}
    int answer=0;for(int x:out)answer+=x;return answer;
  }
